601	func SerializePropertyValue(ctx context.Context, prop resource.PropertyValue, enc config.Encrypter,
602		showSecrets bool,
603	) (any, error) {
604		// Serialize nulls as nil.
605		if prop.IsNull() {
606			return nil, nil
607		}
608	
609		// A computed value marks something that will be determined at a later time. (e.g. the result of
610		// a computation that we don't perform during a preview operation.) We serialize a magic constant
611		// to record its existence.
612		if prop.IsComputed() || prop.IsOutput() {
613			return computedValuePlaceholder, nil
614		}
615	
616		// For arrays, make sure to recurse.
617		if prop.IsArray() {
618			srcarr := prop.ArrayValue()
619			dstarr := make([]any, len(srcarr))
620			for i, elem := range prop.ArrayValue() {
621				selem, err := SerializePropertyValue(ctx, elem, enc, showSecrets)
622				if err != nil {
623					return nil, err
624				}
625				dstarr[i] = selem
626			}
627			return dstarr, nil
628		}
629	
630		// Also for objects, recurse and use naked properties.
631		if prop.IsObject() {
632			return SerializeProperties(ctx, prop.ObjectValue(), enc, showSecrets)
633		}
634	
635		// For assets, we need to serialize them a little carefully, so we can recover them afterwards.
636		if prop.IsAsset() {
637			return prop.AssetValue().Serialize(), nil
638		} else if prop.IsArchive() {
639			return prop.ArchiveValue().Serialize(), nil
640		}
641	
642		// We serialize resource references using a map-based representation similar to assets, archives, and secrets.
643		if prop.IsResourceReference() {
644			ref := prop.ResourceReferenceValue()
645			serialized := map[string]any{
646				resource.SigKey:  resource.ResourceReferenceSig,
647				"urn":            string(ref.URN),
648				"packageVersion": ref.PackageVersion,
649			}
650			if id, hasID := ref.IDString(); hasID {
651				serialized["id"] = id
652			}
653			return serialized, nil
654		}
655	
656		if prop.IsSecret() {
657			// Since we are going to encrypt property value, we can elide encrypting sub-elements. We'll mark them as
658			// "secret" so we retain that information when deserializing the overall structure, but there is no
659			// need to double encrypt everything.
660			value, err := SerializePropertyValue(ctx, prop.SecretValue().Element, config.NopEncrypter, showSecrets)
661			if err != nil {
662				return nil, err
663			}
664			bytes, err := json.Marshal(value)
665			if err != nil {
666				return nil, fmt.Errorf("encoding serialized property value: %w", err)
667			}
668			plaintext := string(bytes)
669	
670			secret := apitype.SecretV1{
671				Sig: resource.SecretSig,
672			}
673	
674			if showSecrets {
675				secret.Plaintext = plaintext
676			} else {
677				// If the encrypter is a batchEncrypter, use the Enqueue method to asynchronously encrypt the secret value.
678				if batchEncrypter, ok := enc.(BatchEncrypter); ok {
679					err = batchEncrypter.Enqueue(ctx, prop.SecretValue(), plaintext, &secret)
680					if err != nil {
681						return nil, fmt.Errorf("enqueuing secret value for encryption: %w", err)
682					}
683				} else {
684					ciphertext, err := enc.EncryptValue(ctx, plaintext)
685					if err != nil {
686						return nil, fmt.Errorf("failed to encrypt secret value: %w", err)
687					}
688					secret.Ciphertext = ciphertext
689				}
690			}
691	
692			return &secret, nil
693		}
694	
695		// Floats need special handling for Inf and NaN.
696		if prop.IsNumber() && (math.IsNaN(prop.NumberValue()) || math.IsInf(prop.NumberValue(), 0)) {
697			// We just save this as hexadecimal strings to preserve precision.
698			bits := math.Float64bits(prop.NumberValue())
699			hex := fmt.Sprintf("%016x", bits)
700			return map[string]any{
701				resource.SigKey: floatSignature,
702				"value":         hex,
703			}, nil
704		}
705	
706		// All others are returned as-is.
707		return prop.V, nil
708	}
