710	// DeserializeResource turns a serialized resource back into its usual form.
711	func DeserializeResource(res apitype.ResourceV3, dec config.Decrypter) (*resource.State, error) {
712		// Deserialize the resource properties, if they exist.
713		inputs, err := DeserializeProperties(res.Inputs, dec)
714		if err != nil {
715			return nil, err
716		}
717		outputs, err := DeserializeProperties(res.Outputs, dec)
718		if err != nil {
719			return nil, err
720		}

